400	// FetchMetadataBranch fetches the entire/checkpoints/v1 branch from origin and
401	// creates/updates the local branch. The fetch is unfiltered (no --filter=blob:none)
402	// because callers (resume, explain) need blob content, not just tree structure.
403	func FetchMetadataBranch(ctx context.Context) error {
404		return fetchMetadataFromOrigin(ctx, false /* shallow */, true /* noFilter */)
405	}
406	
407	// FetchMetadataTreeOnly fetches the tip of the entire/checkpoints/v1 branch
408	// from origin with --depth=1, downloading only the latest commit and its tree
409	// objects. After this call, tree navigation via go-git works but blob reads
410	// will fail for objects that weren't previously fetched.
411	func FetchMetadataTreeOnly(ctx context.Context) error {
412		return fetchMetadataFromOrigin(ctx, true /* shallow */, false /* noFilter */)
413	}
414	
415	// fetchMetadataFromOrigin fetches the v1 metadata branch from origin into the
416	// remote-tracking ref refs/remotes/origin/<branch>, then safely advances the
417	// local branch to match. When shallow is true, --depth=1 is added so only
418	// the tip is downloaded. When noFilter is true, --filter=blob:none is suppressed
419	// so blob content is included.
420	func fetchMetadataFromOrigin(ctx context.Context, shallow, noFilter bool) error {
421		branchName := paths.MetadataBranchName
422	
423		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
424		defer cancel()
425	
426		fetchTarget, err := remote.ResolveFetchTarget(ctx, "origin")
427		if err != nil {
428			return fmt.Errorf("failed to resolve fetch target: %w", err)
429		}
430	
431		refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
432	
433		output, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
434			Remote:   fetchTarget,
435			RefSpecs: []string{refSpec},
436			NoTags:   true,
437			Shallow:  shallow,
438			NoFilter: noFilter,
439		})
440		if fetchErr != nil {
441			if ctx.Err() == context.DeadlineExceeded {
442				return errors.New("fetch timed out after 2 minutes")
443			}
444			return formatFilteredFetchError("failed to fetch "+branchName, fetchTarget, output, fetchErr)
445		}
446	
