// TestExplain_CheckpointSucceedsAfterTreelessFetch covers the partial-clone
// scenario the original bug surfaced in: a collaborator does a treeless
// fetch (--filter=blob:none) of the metadata branch. Tree entries land
// locally so ListCommitted can find the checkpoint, but the metadata.json
// blob is absent from go-git's view. Without the blob fetcher + cat-file
// fallback, ReadCommitted returned (nil, nil) which the resolver translated
// to "checkpoint not found" — even though the checkpoint genuinely exists.
//
// Regression test for: explain failing with "no checkpoint or commit found"
// against a checkpoint_remote-style setup with filtered_fetches enabled.
func TestExplain_CheckpointSucceedsAfterTreelessFetch(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)

	bareRemoteURL := env.SetupBareRemote()

	session := env.NewSession()
	transcriptPath := session.CreateTranscript("Treeless v1 prompt", []FileChange{
		{Path: "treeless_v1.go", Content: "package treeless"},
	})
	require.NoError(t, env.SimulateUserPromptSubmitWithPromptAndTranscriptPath(session.ID, "Treeless v1 prompt", transcriptPath))
	env.WriteFile("treeless_v1.go", "package treeless")
	env.GitAdd("treeless_v1.go")
	require.NoError(t, env.SimulateStop(session.ID, transcriptPath))
	env.GitCommitWithShadowHooks("Add treeless v1 feature", "treeless_v1.go")

	checkpointID := env.GetLatestCheckpointID()
	require.NotEmpty(t, checkpointID, "expected a checkpoint after condensation")

	env.RunPrePush("origin")

	// Wipe local v1 metadata refs and re-fetch with --filter=blob:none.
	// This leaves trees locally but no blobs — the exact partial-clone state
	// that reproduced the original bug.
	repo, err := git.PlainOpen(env.RepoDir)
	require.NoError(t, err)
	_ = repo.Storer.RemoveReference(plumbing.NewBranchReferenceName(paths.MetadataBranchName))
	_ = repo.Storer.RemoveReference(plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName))

	refspec := "+refs/heads/" + paths.MetadataBranchName + ":refs/heads/" + paths.MetadataBranchName
	cmd := exec.CommandContext(t.Context(), "git", "fetch", "--filter=blob:none", "--depth=1", "--no-tags", bareRemoteURL, refspec)
	cmd.Dir = env.RepoDir
	cmd.Env = testutil.GitIsolatedEnv()
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("treeless fetch failed: %v\n%s", err, out)
	}

	// Sanity-check: verify the local branch tip is set but at least one
	// metadata.json blob is genuinely missing from the local store. Without
	// this assertion the test would silently pass even if the treeless fetch
	// somehow grabbed blobs.
	_, err = repo.Storer.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName))
	require.NoError(t, err, "treeless fetch should have set the local metadata branch")
	requireSomeMetadataBlobMissing(t, env.RepoDir, checkpointID)

	output := env.RunCLI("explain", "--checkpoint", checkpointID)
	require.Contains(t, output, "Treeless v1 prompt",
		"explain should succeed and surface the prompt despite blobs being absent locally")
}

// TestExplain_CheckpointV2SucceedsAfterTreelessFetch is the v2 mirror of
// TestExplain_CheckpointSucceedsAfterTreelessFetch — verifies the same
// blob-missing scenario works against the v2 /main ref.
func TestExplain_CheckpointV2SucceedsAfterTreelessFetch(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)

	env.PatchSettings(map[string]any{
		"strategy_options": map[string]any{
			"checkpoints_v2": true,
			"push_v2_refs":   true,
		},
	})

	bareRemoteURL := env.SetupBareRemote()

	session := env.NewSession()
	transcriptPath := session.CreateTranscript("Treeless v2 prompt", []FileChange{
		{Path: "treeless_v2.go", Content: "package treeless"},
	})
	require.NoError(t, env.SimulateUserPromptSubmitWithPromptAndTranscriptPath(session.ID, "Treeless v2 prompt", transcriptPath))
	env.WriteFile("treeless_v2.go", "package treeless")
	env.GitAdd("treeless_v2.go")
	require.NoError(t, env.SimulateStop(session.ID, transcriptPath))
	env.GitCommitWithShadowHooks("Add treeless v2 feature", "treeless_v2.go")

	checkpointID := env.GetLatestCheckpointID()
	require.NotEmpty(t, checkpointID, "expected a checkpoint after condensation")

	env.RunPrePush("origin")

	// Wipe BOTH v1 and v2 metadata refs, then refetch only the v2 /main ref
	// treelessly. This forces explain to use the v2 read path against a
	// repo where blobs are missing — the v2 mirror of the original bug.
	repo, err := git.PlainOpen(env.RepoDir)
	require.NoError(t, err)
	for _, ref := range []plumbing.ReferenceName{
		plumbing.NewBranchReferenceName(paths.MetadataBranchName),
		plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName),
		plumbing.ReferenceName(paths.V2MainRefName),
		plumbing.ReferenceName(paths.V2FullCurrentRefName),
	} {
		_ = repo.Storer.RemoveReference(ref)
	}

	v2Refspec := "+" + paths.V2MainRefName + ":" + paths.V2MainRefName
	cmd := exec.CommandContext(t.Context(), "git", "fetch", "--filter=blob:none", "--depth=1", "--no-tags", bareRemoteURL, v2Refspec)
	cmd.Dir = env.RepoDir
	cmd.Env = testutil.GitIsolatedEnv()
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("v2 treeless fetch failed: %v\n%s", err, out)
	}

	_, err = repo.Storer.Reference(plumbing.ReferenceName(paths.V2MainRefName))
	require.NoError(t, err, "treeless fetch should have set the v2 /main ref")

	output := env.RunCLI("explain", "--checkpoint", checkpointID)
	require.Contains(t, output, "Treeless v2 prompt",
		"explain should succeed against v2 with blobs absent locally")
}

// requireSomeMetadataBlobMissing fails the test if every blob entry in the
// checkpoint's v1 metadata subtree is locally accessible. Used to verify a
// treeless fetch genuinely produced a blob-missing state before exercising
// the read path.
func requireSomeMetadataBlobMissing(t *testing.T, repoDir, checkpointID string) {
	t.Helper()
	repo, err := git.PlainOpen(repoDir)
	require.NoError(t, err)
	ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	require.NoError(t, err)
	commit, err := repo.CommitObject(ref.Hash())
	require.NoError(t, err)
	rootTree, err := commit.Tree()
	require.NoError(t, err)
	cpSubtree, err := rootTree.Tree(checkpointID[:2] + "/" + checkpointID[2:])
	require.NoError(t, err)

	if _, err := cpSubtree.File(paths.MetadataFileName); err != nil {
		// File entry not visible at all — counts as "missing".
		return
	}
	// File entry exists; check whether the blob is actually loadable. After
	// --filter=blob:none, FindEntry succeeds but Contents() should fail
	// (ErrFileNotFound surfaces from missing-blob lookups in go-git).
	for _, entry := range cpSubtree.Entries {
		if !entry.Mode.IsFile() {
			continue
		}
		if _, err := repo.BlobObject(entry.Hash); err != nil {
			return // missing blob found; treeless state confirmed
		}
	}
	t.Fatalf("expected at least one v1 metadata blob to be missing locally after --filter=blob:none fetch (cp=%s)", checkpointID)
}
