		}
		if _, err := repo.BlobObject(entry.Hash); err != nil {
			return // confirmed: at least one blob is missing
		}
	}
	t.Fatalf("expected at least one metadata blob to be missing in fresh treeless clone (cp=%s, v2=%v)", checkpointID, isV2)
}

