73		_, rootTreeHash, err := s.GetRefState(refName)
74		if err != nil {
75			return []CommittedInfo{}, nil //nolint:nilerr // No /main ref means empty list
76		}
77	
78		rootTree, err := s.repo.TreeObject(rootTreeHash)
79		if err != nil {
80			return []CommittedInfo{}, nil //nolint:nilerr // Unreadable tree means no listable entries
81		}
82	
83		var checkpoints []CommittedInfo
84	
85		_ = WalkCheckpointShards(s.repo, rootTree, func(checkpointID id.CheckpointID, cpTreeHash plumbing.Hash) error { //nolint:errcheck // callback never returns errors
86			checkpointTree, cpTreeErr := s.repo.TreeObject(cpTreeHash)
87			if cpTreeErr != nil {
88				logging.Debug(ctx, "v2 ListCommitted: skipping unreadable checkpoint tree",
89					slog.String("checkpoint_id", checkpointID.String()),
90					slog.String("error", cpTreeErr.Error()))
91				return nil
92			}
93	
94			info := CommittedInfo{CheckpointID: checkpointID}
95	
96			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
97				if content, contentErr := metadataFile.Contents(); contentErr == nil {
98					var summary CheckpointSummary
99					if unmarshalErr := json.Unmarshal([]byte(content), &summary); unmarshalErr != nil {
100						logging.Debug(ctx, "v2 ListCommitted: skipping malformed metadata",
101							slog.String("checkpoint_id", checkpointID.String()),
102							slog.String("error", unmarshalErr.Error()))
103					} else {
104						info.CheckpointsCount = summary.CheckpointsCount
105						info.FilesTouched = summary.FilesTouched
106						info.SessionCount = len(summary.Sessions)
107	
108						if len(summary.Sessions) > 0 {
109							latestIndex := len(summary.Sessions) - 1
110							latestDir := strconv.Itoa(latestIndex)
111							if sessionTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
112								if sessionMetadataFile, smErr := sessionTree.File(paths.MetadataFileName); smErr == nil {
113									if sessionContent, scErr := sessionMetadataFile.Contents(); scErr == nil {
114										var sessionMetadata CommittedMetadata
115										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
116											info.Agent = sessionMetadata.Agent
117											info.SessionID = sessionMetadata.SessionID
118											info.CreatedAt = sessionMetadata.CreatedAt
119										}
120									}
121								}
122							}
123						}
124					}
125				}
126			}
127	
128			checkpoints = append(checkpoints, info)
129			return nil
130		})
131	
132		sort.Slice(checkpoints, func(i, j int) bool {
133			return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
134		})
135	
136		return checkpoints, nil
137	}
